import{bV as e,aL as o,u as a,G as i}from"./chunks/framework.DvBUyM1S.js";const b=JSON.parse('{"title":"钉钉多端 H5 表格组件选型（Vant 无 Table 的替代路径）","description":"","frontmatter":{"id":"PB-20260902-002","type":"playbook","title":"钉钉多端 H5 表格组件选型（Vant 无 Table 的替代路径）","tags":["dingtalk","table","vue3","mobile"],"status":"draft","source":"conversation:2026-09-02","created":"2026-09-02T00:00:00.000Z","updated":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/dingtalk-h5-table-component.md","filePath":"playbooks/dingtalk-h5-table-component.md"}'),d={name:"playbooks/dingtalk-h5-table-component.md"};function l(s,t,n,c,r,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="钉钉多端-h5-表格组件选型-vant-无-table-的替代路径" tabindex="-1">钉钉多端 H5 表格组件选型（Vant 无 Table 的替代路径） <a class="header-anchor" href="#钉钉多端-h5-表格组件选型-vant-无-table-的替代路径" aria-label="Permalink to &quot;钉钉多端 H5 表格组件选型（Vant 无 Table 的替代路径）&quot;">​</a></h1><p>See Also: <a href="./../playbooks/dingtalk-multi-platform-viewport">PB-20260902-001 钉钉多端 H5 视口适配</a>、<a href="./../playbooks/dingtalk-h5-microapp">PB-20260824-001 uniapp 接入钉钉 H5 微应用</a></p><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ul><li><strong>Vant 2/3/4 官方都没有 Table 组件</strong>，也没有列入路线图。官方定位是「原子化高频组件」，复杂表格交社区。社区 <code>vant-table</code> 已停更，别用。</li><li>主流移动端 UI 库里 <strong>只有 TDesign Mobile Vue 原生自带 Table</strong>；Vant / NutUI / antd-mobile / Varlet 均无。</li><li>钉钉四端（iOS / Android / Mac 客户端 / Windows 客户端）共用一套表格的<strong>最低成本路径</strong>：TDesign Mobile Vue 的 <code>t-table</code> 按需引入，与 Vant 混用。</li></ul><h2 id="选型矩阵" tabindex="-1">选型矩阵 <a class="header-anchor" href="#选型矩阵" aria-label="Permalink to &quot;选型矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>包</th><th>体积</th><th>适用场景</th><th>风险</th></tr></thead><tbody><tr><td>TDesign Mobile Vue Table</td><td><code>tdesign-mobile-vue</code></td><td>按需引入，小</td><td>移动端为主、PC 钉钉也要能看；列数 ≤ 15</td><td>与 Vant 混用需统一主题色</td></tr><tr><td>Vant + 手写 table</td><td>无新依赖</td><td>~0</td><td>列少（≤6）、只读、卡片式</td><td>自己实现 sticky 首列 + 横向滚动</td></tr><tr><td>vxe-table（纯表格模式）</td><td><code>vxe-table</code> + <code>vxe-pc-ui</code></td><td>大（数百 KB）</td><td>列多、虚拟滚动、行编辑、合并单元格</td><td>桌面优先；移动端需手动压行高、关 hover</td></tr><tr><td>AG Grid Community</td><td><code>ag-grid-vue3</code></td><td>大</td><td>在线编辑、Excel 级交互</td><td>中文文档弱、企业版才有的功能易踩坑</td></tr></tbody></table><p>决策树：</p><ol><li>列 ≤ 6 且只读 → <strong>手写 table + Vant</strong>（<code>van-list</code> 上拉加载 + <code>van-skeleton</code> 占位）</li><li>列 7–15、需要固定首列/表头、跨四端 → <strong>TDesign Mobile Vue <code>t-table</code></strong></li><li>列 &gt; 15、或需要虚拟滚动 / 行内编辑 / 列拖拽 → <strong>vxe-table</strong>（若 PC 主项目已在用，直接复用同一套列定义最省）</li></ol><h2 id="钉钉四端适配要点-表格专属" tabindex="-1">钉钉四端适配要点（表格专属） <a class="header-anchor" href="#钉钉四端适配要点-表格专属" aria-label="Permalink to &quot;钉钉四端适配要点（表格专属）&quot;">​</a></h2><ol><li><strong>PC 端视口是宽的</strong>——<code>t-table</code> 与手写 table 都要设 <code>max-width</code> 居中，否则在 Windows 客户端 1600px 宽下拉成一条线。视口方案见 PB-20260902-001。</li><li><strong>iOS 横向滚动惯性</strong>——滚动容器必须加：<div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.table-scroll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">overflow-x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-webkit-overflow-scrolling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">touch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div>缺 <code>-webkit-overflow-scrolling</code> 时 iOS 上滑动会「粘手」，用户以为页面卡死。</li><li><strong>固定首列用 <code>position: sticky; left: 0</code></strong>——不要引入 <code>position: fixed</code> 方案，会与钉钉容器的滚动层级打架。sticky 的祖先链上任何节点有 <code>overflow: hidden</code> 都会失效，检查到 <code>#app</code> 为止。</li><li><strong>表头吸顶</strong>——<code>position: sticky; top: 0</code> 会顶到钉钉自带导航栏下面；<code>top</code> 值需按 <code>dd.env.platform === &#39;ios&#39; ? 44 : 0</code> 之类动态给，或直接用钉钉 JSAPI 关掉自带导航自行实现。</li><li><strong>点击延迟</strong>——<code>t-table</code> 的行点击事件在 iOS 上有 300ms 问题，配 <code>viewport</code> 的 <code>width=device-width</code> 已能规避大部分，剩余用 <code>touch-action: manipulation</code>。</li><li><strong>PC 端无下拉刷新手势</strong>——分页/加载更多要做成显式按钮，不要只靠 <code>van-list</code> 的上拉触底（PC 端永远触不了底）。</li></ol><h2 id="验证清单" tabindex="-1">验证清单 <a class="header-anchor" href="#验证清单" aria-label="Permalink to &quot;验证清单&quot;">​</a></h2><ul><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>钉钉 iOS / Android 真机：横向滑动跟手、首列不跟着滚</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>钉钉 Mac / Windows 客户端：表格不巨型化、有最大宽度、居中</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>PC 端可翻页（无触底事件）</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>空态 / 骨架屏 / 加载失败三态齐全</li><li class="todo"><input class="todo-checkbox" type="checkbox" disabled>与 Vant 混用时主题变量未互相覆盖（检查 CSS 变量作用域）</li></ul><blockquote><p><strong>待核实</strong>：TDesign Mobile Vue 的 <code>t-table</code> 具体 API（固定列属性名、是否支持横向滚动配置）以上游文档为准，本条目落 <code>draft</code> 因尚未在钉钉四端实测。</p></blockquote>',13)])])}const k=e(d,[["render",l]]);export{b as __pageData,k as default};
